const fs = require('fs');

let data;
try {
  data = fs.readFileSync(0, 'utf8');
} catch (e) {
  data = fs.readFileSync('/dev/stdin', 'utf8');
}

const tokens = data.split(/\s+/).filter(s => s.length > 0);
let p = 0;
const L = parseInt(tokens[p++], 10);
const C = parseInt(tokens[p++], 10);

const grid = new Array(L);
const rowSum = new Array(L);
for (let i = 0; i < L; i++) {
  const row = new Array(C);
  for (let j = 0; j < C; j++) row[j] = tokens[p++];
  rowSum[i] = parseInt(tokens[p++], 10);
  grid[i] = row;
}
const colSum = new Array(C);
for (let j = 0; j < C; j++) colSum[j] = parseInt(tokens[p++], 10);

// Mapa de variáveis desconhecidas (nome -> nº de ocorrências) por linha e por coluna
const rowMap = new Array(L);
const colMap = new Array(C);
for (let i = 0; i < L; i++) {
  const m = new Map();
  for (let j = 0; j < C; j++) {
    const v = grid[i][j];
    m.set(v, (m.get(v) || 0) + 1);
  }
  rowMap[i] = m;
}
for (let j = 0; j < C; j++) {
  const m = new Map();
  for (let i = 0; i < L; i++) {
    const v = grid[i][j];
    m.set(v, (m.get(v) || 0) + 1);
  }
  colMap[j] = m;
}

// Para cada variável: em quais linhas/colunas aparece e com quantas ocorrências
const rowsOfVar = new Map();
const colsOfVar = new Map();
for (let i = 0; i < L; i++) {
  for (const entry of rowMap[i]) {
    let arr = rowsOfVar.get(entry[0]);
    if (!arr) { arr = []; rowsOfVar.set(entry[0], arr); }
    arr.push([i, entry[1]]);
  }
}
for (let j = 0; j < C; j++) {
  for (const entry of colMap[j]) {
    let arr = colsOfVar.get(entry[0]);
    if (!arr) { arr = []; colsOfVar.set(entry[0], arr); }
    arr.push([j, entry[1]]);
  }
}

// Soma residual de cada linha/coluna (soma original - contribuições já resolvidas)
const rowRes = rowSum.slice();
const colRes = colSum.slice();
const resolved = new Map();

// Fila de processamento (tipo 0 = linha, tipo 1 = coluna)
const queue = [];
const inQR = new Array(L).fill(false);
const inQC = new Array(C).fill(false);
for (let i = 0; i < L; i++) { queue.push(0, i); inQR[i] = true; }
for (let j = 0; j < C; j++) { queue.push(1, j); inQC[j] = true; }

let head = 0;
while (head < queue.length) {
  const t = queue[head++];
  const idx = queue[head++];
  if (t === 0) inQR[idx] = false; else inQC[idx] = false;

  const m = (t === 0) ? rowMap[idx] : colMap[idx];
  if (m.size !== 1) continue;

  let v = null, cnt = 0;
  for (const kv of m) { v = kv[0]; cnt = kv[1]; }
  if (resolved.has(v)) continue;

  const res = (t === 0) ? rowRes[idx] : colRes[idx];
  let val;
  if (cnt === 1) {
    val = res;
  } else {
    // única variável distinta desconhecida, mas com múltiplas ocorrências
    if (res % cnt !== 0) continue;
    val = res / cnt;
  }
  if (val === 0) val = 0; // normaliza -0

  resolved.set(v, val);

  const rl = rowsOfVar.get(v) || [];
  for (let x = 0; x < rl.length; x++) {
    const ri = rl[x][0];
    rowMap[ri].delete(v);
    rowRes[ri] -= val * rl[x][1];
    if (!inQR[ri]) { inQR[ri] = true; queue.push(0, ri); }
  }
  const cl = colsOfVar.get(v) || [];
  for (let x = 0; x < cl.length; x++) {
    const cj = cl[x][0];
    colMap[cj].delete(v);
    colRes[cj] -= val * cl[x][1];
    if (!inQC[cj]) { inQC[cj] = true; queue.push(1, cj); }
  }
}

const names = Array.from(rowsOfVar.keys()).sort();
let out = '';
for (const n of names) out += n + ' ' + resolved.get(n) + '\n';
process.stdout.write(out);
